WITH Base AS (SELECT * FROM orders WHERE order_date BETWEEN '2025-04-29' AND '2025-10-01' AND shipping_fee BETWEEN 10 AND 36), orders_stats AS (SELECT DATE_FORMAT(order_date, 'yyyy-MM') AS order_month, SUM(CASE WHEN status = 'SHIPPED' THEN 1 ELSE 0 END) AS shipped_count, ROUND(STDDEV(shipping_fee), 2) AS stddev_shipping_fee FROM Base GROUP BY DATE_FORMAT(order_date, 'yyyy-MM')) SELECT order_month, shipped_count, stddev_shipping_fee FROM orders_stats ORDER BY shipped_count;
